select users.display_name, (select count(*)::text from logs where id='52fdfc07-2182-454f-963f-5f0f9a621d72') as logs, (select count(*)::text from contest_logs where log_id='52fdfc07-2182-454f-963f-5f0f9a621d72') as contest_logs, (select count(*)::text from log_tags where log_id='52fdfc07-2182-454f-963f-5f0f9a621d72') as tags, (select count(*)::text from leaderboard_outbox) as outbox from users where id='11111111-1111-4111-8111-111111111111';
